package com.example;

import org.apache.camel.builder.RouteBuilder;
import org.springframework.stereotype.Component;

@Component
public class OrderRoute extends RouteBuilder {

    @Override
    public void configure() throws Exception {
        from("timer:orderPoll?period=5000")
            .to("log:orders");
    }
}

public class HeartbeatRoute extends RouteBuilder {
    @Override
    public void configure() {
        from("timer:heartbeat?period=5000")
            .routeId("heartbeat")
            .log("Tick ${exchangeProperty.CamelTimerCounter}");
    }
}

public class OrdersCopyRoute extends RouteBuilder {
    @Override
    public void configure() {
        from("file:data/incoming?noop=true")
            .routeId("orders-copy")
            .log("Copying ${header.CamelFileName}")
            .to("file:data/outgoing");
    }
}

from("direct:validateOrder")
    .process(exchange -> {
        String body = exchange.getMessage().getBody(String.class);
        if (body == null || body.isBlank()) {
            throw new IllegalArgumentException("empty order body");
        }
    });

from("file:data/incoming?noop=true")
    .routeId("orders-copy")
    .to("direct:validateOrder")
    .log("Copying ${header.CamelFileName}")
    .to("file:data/outgoing");

.process(exchange -> {
